import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int T = Integer.parseInt(st.nextToken()); PrintWriter out = new PrintWriter(System.out); while (T-- > 0) { int N = Integer.parseInt(br.readLine()); int[] A = new int[N]; st = new StringTokenizer(br.readLine()); for (int i = 0; i < N; i++) { A[i] = Integer.parseInt(st.nextToken()); } long maxSum = 0; int minOps = 0; for (int i = 0; i < N; i++) { for (int j = i; j < N; j++) { long currentSum = 0; int currentOps = 0; for (int k = i; k <= j; k++) { if (A[k] > 0) { currentSum += A[k]; } else { currentOps++; } } if (currentSum > maxSum) { maxSum = currentSum; minOps = currentOps; } else if (currentSum == maxSum) { if (maxSum == 0) { minOps = 0; } else { minOps = Math.min(minOps, currentOps); } } } } out.println(minOps); } out.flush(); out.close(); } }